import React, { useEffect, useState } from "react";
import { useOutletContext } from "react-router-dom";

/**
 * Summary tab UI based on TabsUI.xlsx -> Tab1
 * - Yellow: sections
 * - Light green: fields (editable where needed)
 * - Light blue: to-be-fetched (disabled placeholders)
 * - Orange: computed (uneditable)
 */
export default function SummaryTab() {
  const { intakeNumber, projectDetails } = useOutletContext();
  const [form, setForm] = useState({
    // Project Details (light blue values = fetch later; populate with projectDetails where possible)
    projectNumberAndName: projectDetails ? `${projectDetails.intake_number} - ${projectDetails.intake_name}` : "",
    releaseName: projectDetails?.release || "",
    applicationsImpacted: "", // light blue -> fetched later
    automationLeadName: projectDetails?.automation_qe_lead || "",
    // Test Case / Deals Count (sample inputs)
    withStubPerDay: "",         // light green: user entry
    withoutStubPerDay: "",      // light green: user entry
    testExecCount: "",          // light green: user entry
    totalDaysWithStub: 0,       // orange: computed
    totalDaysWithoutStub: 0,    // orange: computed
    savingsDays: 0,             // orange: computed
    savingsDollar: 0,           // orange: computed (uses a simple rate for now)
  });

  const RATE_PER_DAY = 1000; // placeholder; adjust if Excel specifies another rate

  const onChange = (k, v) => {
    setForm((prev) => ({ ...prev, [k]: v }));
  };

  // Recompute orange cells whenever inputs change
  useEffect(() => {
    const L = Number(form.testExecCount || 0);
    const withPD = Number(form.withStubPerDay || 0);
    const withoutPD = Number(form.withoutStubPerDay || 0);

    const totalWith = L * withPD;
    const totalWithout = L * withoutPD;
    const savings = Math.max(totalWithout - totalWith, 0);
    const savings$ = savings * RATE_PER_DAY;

    setForm((prev) => ({
      ...prev,
      totalDaysWithStub: totalWith,
      totalDaysWithoutStub: totalWithout,
      savingsDays: savings,
      savingsDollar: savings$,
    }));
  }, [form.testExecCount, form.withStubPerDay, form.withoutStubPerDay]);

  return (
    <div className="tab-wrap">
      <div className="tab-section tab-section-yellow">Project Details</div>
      <div className="grid-2">
        <label className="tab-label tab-label-green">Project Number and Name</label>
        <input className="tab-input tab-input-blue" value={form.projectNumberAndName} disabled />

        <label className="tab-label tab-label-green">Release Name</label>
        <input className="tab-input tab-input-blue" value={form.releaseName} disabled />

        <label className="tab-label tab-label-green">Applications Impacted</label>
        <input className="tab-input tab-input-blue" value={form.applicationsImpacted} placeholder="Auto (DB)" disabled />

        <label className="tab-label tab-label-green">Automation Lead Name</label>
        <input className="tab-input tab-input-blue" value={form.automationLeadName} disabled />
      </div>

      <div className="tab-section tab-section-yellow">Test Case / Deals Count</div>
      <div className="grid-2">
        <label className="tab-label tab-label-green">With Stub per day</label>
        <input className="tab-input" type="number" value={form.withStubPerDay} onChange={(e) => onChange("withStubPerDay", e.target.value)} />

        <label className="tab-label tab-label-green">Without Stub per day</label>
        <input className="tab-input" type="number" value={form.withoutStubPerDay} onChange={(e) => onChange("withoutStubPerDay", e.target.value)} />

        <label className="tab-label tab-label-green"># Test Case execution Count</label>
        <input className="tab-input" type="number" value={form.testExecCount} onChange={(e) => onChange("testExecCount", e.target.value)} />

        <label className="tab-label tab-label-orange"># Total Days of effort - With Stub</label>
        <input className="tab-input tab-input-orange" value={form.totalDaysWithStub} disabled />

        <label className="tab-label tab-label-orange"># Total Days of effort - Without Stub</label>
        <input className="tab-input tab-input-orange" value={form.totalDaysWithoutStub} disabled />

        <label className="tab-label tab-label-orange">Savings in Days</label>
        <input className="tab-input tab-input-orange" value={form.savingsDays} disabled />

        <label className="tab-label tab-label-orange">Savings in Dollar Value</label>
        <input className="tab-input tab-input-orange" value={form.savingsDollar} disabled />
      </div>
    </div>
  );
}
